SET XACT_ABORT ON;\nBEGIN TRANSACTION;\n\nIF COL_LENGTH('dbo.GameResult', 'PlayerTokenHash') IS NOT NULL\n   AND COL_LENGTH('dbo.GameResult', 'CredentialHash') IS NULL\nBEGIN\n    EXEC sp_rename 'dbo.GameResult.PlayerTokenHash', 'CredentialHash', 'COLUMN';\nEND;\n\nIF COL_LENGTH('dbo.AccountScoreAward', 'PlayerTokenHash') IS NOT NULL\n   AND COL_LENGTH('dbo.AccountScoreAward', 'CredentialHash') IS NULL\nBEGIN\n    EXEC sp_rename 'dbo.AccountScoreAward.PlayerTokenHash', 'CredentialHash', 'COLUMN';\nEND;\n\nIF EXISTS (\n    SELECT GameHash, AccountId\n    FROM dbo.AccountScoreAward\n    GROUP BY GameHash, AccountId\n    HAVING COUNT(*) > 1\n)\n    THROW 50010, 'Resolve duplicate account awards for the same game before applying migration 010.', 1;\n\nIF NOT EXISTS (\n    SELECT 1 FROM sys.indexes\n    WHERE object_id = OBJECT_ID('dbo.AccountScoreAward')\n      AND name = 'UX_AccountScoreAward_Game_Account'\n)\nBEGIN\n    CREATE UNIQUE INDEX UX_AccountScoreAward_Game_Account\n        ON dbo.AccountScoreAward (GameHash, AccountId);\nEND;\n\nCOMMIT;\n
